VALUES
  ('nfpa70e_global:v1', 'nfpa70e_global', 1,
   'NFPA 70E readiness checklist',
   'A customizable readiness review based on high-level electrical safety themes. This is not an official NFPA checklist, certification, or substitute for the complete standard and qualified professional judgment.',
   '{"sections":[{"id":"program","items":[{"id":"program-1","prompt":"A documented electrical safety program is available to affected workers.","required":true,"responseType":"check"},{"id":"program-2","prompt":"Electrical safety responsibilities are assigned and understood.","required":true,"responseType":"check"},{"id":"program-3","prompt":"The program considers the condition of maintenance of electrical equipment.","required":true,"responseType":"check"}],"title":"Electrical safety program"},{"id":"training","items":[{"id":"training-1","prompt":"Workers are qualified for the specific equipment and tasks they perform.","required":true,"responseType":"check"},{"id":"training-2","prompt":"Electrical safety and emergency response training records are current.","required":true,"responseType":"check"},{"id":"training-3","prompt":"Unqualified workers receive training appropriate to their electrical exposure.","required":true,"responseType":"check"}],"title":"Training and qualification"},{"id":"planning","items":[{"id":"planning-1","prompt":"Job planning identifies potential shock and arc-flash hazards.","required":true,"responseType":"check"},{"id":"planning-2","prompt":"Required shock and arc-flash risk assessments are documented and current.","required":true,"responseType":"check"},{"id":"planning-3","prompt":"Energized work is justified and permitted only when applicable requirements are met.","required":true,"responseType":"check"}],"title":"Risk assessment and job planning"},{"id":"safe-condition","items":[{"id":"safe-condition-1","prompt":"A documented policy prioritizes establishing an electrically safe work condition.","required":true,"responseType":"check"},{"id":"safe-condition-2","prompt":"Lockout/tagout and absence-of-voltage verification procedures are followed.","required":true,"responseType":"check"},{"id":"safe-condition-3","prompt":"Test instruments are suitable, inspected, and used by qualified people.","required":true,"responseType":"check"}],"title":"Electrically safe work condition"},{"id":"protection","items":[{"id":"protection-1","prompt":"Task-specific PPE is selected from the documented hazard assessment.","required":true,"responseType":"check"},{"id":"protection-2","prompt":"Protective equipment and insulated tools are inspected and maintained.","required":true,"responseType":"check"},{"id":"protection-3","prompt":"Required labels, signs, barriers, and boundaries are current and legible.","required":true,"responseType":"check"}],"title":"PPE, tools, and work area"},{"id":"review","items":[{"id":"review-1","prompt":"Electrical equipment is maintained in a condition appropriate for safe operation.","required":true,"responseType":"check"},{"id":"review-2","prompt":"The electrical safety program is periodically audited.","required":true,"responseType":"check"},{"id":"review-3","prompt":"Deficiencies and corrective actions are documented and tracked to closure.","required":true,"responseType":"check"}],"title":"Maintenance and continuous improvement"}],"version":1}',
   'published', 'system:audit-library', '2026-10-28T00:00:00.000Z');

