INSERT OR IGNORE INTO audit_template_versions
  (id, template_id, version, name, description, definition, status,
   created_by, created_at)
VALUES
  ('us_residential_core_global:v1', 'us_residential_core_global', 1,
   'U.S. residential construction — comprehensive baseline',
   'A comprehensive U.S. baseline for detached one- and two-family homes and townhouses. It combines federal construction-safety controls with model-code, project-document, manufacturer, and workmanship checks. It is not a code-compliance certification; verify State Plan, state, local, project, utility, and product-specific requirements before use.',
   '{"sections":[{"id":"project-readiness","items":[{"id":"res-ready-001","prompt":"The current permit set, approved revisions, and applicable specifications are available to supervisors and inspectors.","required":true,"responseType":"check"},{"id":"res-ready-002","prompt":"Required permits are active, their conditions are understood, and the required inspection sequence is documented.","required":true,"responseType":"check"},{"id":"res-ready-003","prompt":"The project scope identifies whether the work is new construction, alteration, repair, addition, demolition, or a combination.","required":true,"responseType":"check"},{"id":"res-ready-004","prompt":"Responsibility for safety, quality control, inspections, testing, and correction of deficiencies is assigned.","required":true,"responseType":"check"},{"id":"res-ready-005","prompt":"The employer has designated competent or qualified people for activities that require them.","required":true,"responseType":"check"},{"id":"res-ready-006","prompt":"Current work activities have been evaluated for hazards, controls, sequencing, and interactions with other trades.","required":true,"responseType":"check"},{"id":"res-ready-007","prompt":"Emergency contacts, the site address, access instructions, evacuation actions, and worker communication methods are established.","required":true,"responseType":"check"},{"id":"res-ready-008","prompt":"Known underground and overhead utilities are identified before work that could contact or damage them begins.","required":true,"responseType":"check"},{"id":"res-ready-009","prompt":"A current chemical inventory, labels, safety data sheets, and employee hazard-communication training cover materials in use.","required":true,"responseType":"check"},{"id":"res-ready-010","prompt":"For covered renovation work in pre-1978 housing, firm and renovator certifications, occupant notices, and lead-safe work practices are documented.","required":true,"responseType":"check"},{"id":"res-ready-011","prompt":"Submittals, product selections, delegated designs, and required mockups are approved before the affected work begins.","required":true,"responseType":"check"},{"id":"res-ready-012","prompt":"Required hold points, pre-cover inspections, tests, and photo-documentation needs are included in the project schedule.","required":true,"responseType":"check"}],"title":"Project readiness and controls"},{"id":"site-conditions","items":[{"id":"res-site-001","prompt":"Site boundaries, access restrictions, and public protections are appropriate for the location and current work.","required":true,"responseType":"check"},{"id":"res-site-002","prompt":"Vehicle routes, delivery areas, backing controls, and pedestrian paths are separated or actively controlled.","required":true,"responseType":"check"},{"id":"res-site-003","prompt":"Access routes and working areas are stable, reasonably level, adequately illuminated, and clear of uncontrolled openings or debris.","required":true,"responseType":"check"},{"id":"res-site-004","prompt":"Scrap, protruding nails, cords, hoses, packaging, and waste are controlled as work progresses.","required":true,"responseType":"check"},{"id":"res-site-005","prompt":"Stored materials are stable, secured against displacement, and do not overload floors, platforms, or soil edges.","required":true,"responseType":"check"},{"id":"res-site-006","prompt":"Combustible waste, ignition sources, fuel, compressed-gas cylinders, and temporary heating are separated and controlled.","required":true,"responseType":"check"},{"id":"res-site-007","prompt":"Suitable fire extinguishers are accessible, identified, inspected, and located for the work and temporary facilities.","required":true,"responseType":"check"},{"id":"res-site-008","prompt":"Required emergency exits and travel paths remain unobstructed and usable from occupied work areas.","required":true,"responseType":"check"},{"id":"res-site-009","prompt":"Potable water, toilets, handwashing provisions, and sanitation are available and maintained for the workforce.","required":true,"responseType":"check"},{"id":"res-site-010","prompt":"Current weather conditions are addressed, including heat, cold, lightning, wind, ice, rain, and reduced visibility.","required":true,"responseType":"check"},{"id":"res-site-011","prompt":"Signs, tags, barricades, and warnings are visible, legible, and matched to the current hazard.","required":true,"responseType":"check"},{"id":"res-site-012","prompt":"First-aid supplies and prompt medical-response arrangements are available for the site and crew size.","required":true,"responseType":"check"}],"title":"Site conditions and public protection"},{"id":"tools-equipment-exposures","items":[{"id":"res-tools-001","prompt":"Required personal protective equipment is selected for the hazard, fits the worker, is serviceable, and is used correctly.","required":true,"responseType":"check"},{"id":"res-tools-002","prompt":"Workers exposed to flying particles, splashes, harmful light, or similar hazards use suitable eye and face protection.","required":true,"responseType":"check"},{"id":"res-tools-003","prompt":"Workers exposed to head injury use suitable head protection in serviceable condition.","required":true,"responseType":"check"},{"id":"res-tools-004","prompt":"Noise exposure is evaluated and required engineering controls, hearing protection, and hearing-conservation measures are implemented.","required":true,"responseType":"check"},{"id":"res-tools-005","prompt":"When respirators are required, the written program, medical evaluation, fit testing, selection, inspection, and worker training are current.","required":true,"responseType":"check"},{"id":"res-tools-006","prompt":"Silica-generating tasks use the applicable Table 1 controls or a compliant alternative exposure-control method.","required":true,"responseType":"check"},{"id":"res-tools-007","prompt":"Silica housekeeping avoids prohibited dry sweeping, dry brushing, and compressed-air cleaning unless the stated exceptions are met.","required":true,"responseType":"check"},{"id":"res-tools-008","prompt":"Hand and power tools are maintained in safe condition with required guards, controls, handles, and accessories installed.","required":true,"responseType":"check"},{"id":"res-tools-009","prompt":"Circular, table, miter, and other saws have functioning guards and are used with the correct blade, support, and work practices.","required":true,"responseType":"check"},{"id":"res-tools-010","prompt":"Powder-actuated tools are used only by trained workers and are inspected, loaded, stored, and fired using the required safeguards.","required":true,"responseType":"check"},{"id":"res-tools-011","prompt":"Pneumatic tools, hoses, couplings, safety devices, and pressure settings are suitable and secured against accidental disconnection or discharge.","required":true,"responseType":"check"},{"id":"res-tools-012","prompt":"Tools and equipment are de-energized or otherwise controlled before blade changes, clearing jams, adjustment, or maintenance.","required":true,"responseType":"check"},{"id":"res-tools-013","prompt":"Material size, weight, route, grip, team lifting, and mechanical assistance are planned to avoid uncontrolled handling and overexertion.","required":true,"responseType":"check"},{"id":"res-tools-014","prompt":"Motor vehicles and mechanized equipment receive required inspections and have functioning brakes, alarms, lights, controls, and seat belts.","required":true,"responseType":"check"},{"id":"res-tools-015","prompt":"Equipment swing areas, blind spots, backing paths, spotters, exclusion zones, and pedestrian interfaces are controlled.","required":true,"responseType":"check"},{"id":"res-tools-016","prompt":"Crane or hoisting work uses required operator qualifications, inspections, setup, signaling, lift planning, and power-line controls.","required":true,"responseType":"check"},{"id":"res-tools-017","prompt":"Rigging and lifting accessories are identified, inspected, suitable for the load, protected from damage, and used without workers beneath suspended loads.","required":true,"responseType":"check"},{"id":"res-tools-018","prompt":"Welding, cutting, and brazing control cylinders, combustibles, ventilation, screens, fire watch, and required protective equipment.","required":true,"responseType":"check"},{"id":"res-tools-019","prompt":"Potential confined spaces are identified before entry and required coordination, evaluation, permits, controls, and rescue provisions are implemented.","required":true,"responseType":"check"},{"id":"res-tools-020","prompt":"The work plan addresses temperature stress through acclimatization, hydration, rest, shelter, clothing, monitoring, and emergency response as conditions require.","required":true,"responseType":"check"}],"title":"PPE, tools, equipment, and health exposures"},{"id":"demolition-existing","items":[{"id":"res-demo-001","prompt":"Before demolition begins, a competent person has documented the condition of framing, floors, walls, and possible unplanned collapse hazards.","required":true,"responseType":"check"},{"id":"res-demo-002","prompt":"Electric, gas, water, sewer, and other services are shut off, capped, relocated, or otherwise controlled before affected work.","required":true,"responseType":"check"},{"id":"res-demo-003","prompt":"The pre-work assessment addresses asbestos, lead, mold, silica-containing materials, refrigerants, and other suspect hazardous materials.","required":true,"responseType":"check"},{"id":"res-demo-004","prompt":"Load-bearing members are removed only in the planned sequence with required temporary support installed.","required":true,"responseType":"check"},{"id":"res-demo-005","prompt":"Floor openings, wall openings, shafts, and weakened walking surfaces are guarded, covered, or access-controlled.","required":true,"responseType":"check"},{"id":"res-demo-006","prompt":"Debris handling, chutes, drop zones, and disposal routes prevent uncontrolled falling material and public exposure.","required":true,"responseType":"check"},{"id":"res-demo-007","prompt":"Dust-producing demolition uses the required engineering controls, work practices, housekeeping, and respiratory protection.","required":true,"responseType":"check"},{"id":"res-demo-008","prompt":"Workers and stored materials are kept clear of unstable walls, unsupported floors, and active mechanical-demolition zones.","required":true,"responseType":"check"},{"id":"res-demo-009","prompt":"Removed hazardous components, fuel containers, batteries, lamps, and chemicals are segregated and disposed of through approved channels.","required":true,"responseType":"check"},{"id":"res-demo-010","prompt":"Conditions exposed by demolition are documented and design conflicts are resolved before reconstruction conceals them.","required":true,"responseType":"check"}],"title":"Demolition and existing conditions"},{"id":"earthwork-utilities","items":[{"id":"res-earth-001","prompt":"Utility owners have been contacted and underground installations are located, marked, and protected before excavation.","required":true,"responseType":"check"},{"id":"res-earth-002","prompt":"A competent person inspects excavations, adjacent areas, and protective systems before work, daily, and after hazard-increasing events.","required":true,"responseType":"check"},{"id":"res-earth-003","prompt":"Each employee exposed to a cave-in hazard is protected by an applicable sloping, benching, shoring, or shielding system.","required":true,"responseType":"check"},{"id":"res-earth-004","prompt":"Safe access and egress are provided for trenches four feet or more deep so workers travel no more than 25 feet laterally.","required":true,"responseType":"check"},{"id":"res-earth-005","prompt":"Spoil, materials, and equipment are kept at least two feet from excavation edges or retained against falling or rolling in.","required":true,"responseType":"check"},{"id":"res-earth-006","prompt":"Water accumulation, runoff, dewatering, and changing soil conditions are controlled before employees enter an excavation.","required":true,"responseType":"check"},{"id":"res-earth-007","prompt":"Excavation work does not undermine adjacent foundations, pavements, utilities, or structures without an approved support system.","required":true,"responseType":"check"},{"id":"res-earth-008","prompt":"Where a hazardous atmosphere could exist, testing and required ventilation, respiratory protection, and rescue precautions are in place before entry.","required":true,"responseType":"check"},{"id":"res-earth-009","prompt":"Mobile equipment approaching an excavation edge has a clear view, barricade, stop log, or signaler appropriate to the condition.","required":true,"responseType":"check"},{"id":"res-earth-010","prompt":"Subgrade elevation, bearing condition, unsuitable-material removal, and required compaction are accepted before foundations or slabs proceed.","required":true,"responseType":"check"},{"id":"res-earth-011","prompt":"Foundation drainage, granular fill, drainage outlets, and waterproofing access are coordinated before backfill.","required":true,"responseType":"check"},{"id":"res-earth-012","prompt":"Backfill material, lift placement, compaction, and timing do not damage or overload foundation walls, drainage, utilities, or waterproofing.","required":true,"responseType":"check"},{"id":"res-earth-013","prompt":"Final grading and drainage elevations direct water to approved discharge locations without trapping it against the dwelling.","required":true,"responseType":"check"}],"title":"Earthwork, grading, and underground utilities"},{"id":"foundations-concrete-masonry","items":[{"id":"res-found-001","prompt":"Footing excavations are on accepted bearing material at the required dimensions, elevations, and locations before placement.","required":true,"responseType":"check"},{"id":"res-found-002","prompt":"Forms, shores, reshores, and braces are installed and maintained for anticipated vertical and lateral loads.","required":true,"responseType":"check"},{"id":"res-found-003","prompt":"Reinforcing size, grade, spacing, laps, supports, cleanliness, and concrete cover match the approved documents.","required":true,"responseType":"check"},{"id":"res-found-004","prompt":"Exposed reinforcing steel that could impale workers is guarded against the hazard.","required":true,"responseType":"check"},{"id":"res-found-005","prompt":"Anchor bolts, hold-downs, embeds, sleeves, beam pockets, and utility penetrations are correctly located and secured before placement.","required":true,"responseType":"check"},{"id":"res-found-006","prompt":"Required capillary breaks, granular base, vapor retarder, and sealed penetrations are complete before slab placement.","required":true,"responseType":"check"},{"id":"res-found-007","prompt":"Concrete delivery documentation confirms the approved mix and prohibited field water or admixture changes have not occurred.","required":true,"responseType":"check"},{"id":"res-found-008","prompt":"Required concrete sampling, temperature, slump, air, and strength specimens are taken and documented by the designated testing party.","required":true,"responseType":"check"},{"id":"res-found-009","prompt":"Concrete is placed without harmful segregation, cold joints, displaced reinforcement, or unplanned interruption.","required":true,"responseType":"check"},{"id":"res-found-010","prompt":"Consolidation, finishing, jointing, surface tolerances, and curing match the approved placement plan and weather conditions.","required":true,"responseType":"check"},{"id":"res-found-011","prompt":"Hot- or cold-weather concrete protections and curing controls are in place when conditions require them.","required":true,"responseType":"check"},{"id":"res-found-012","prompt":"Foundation dampproofing or waterproofing is continuous, undamaged, correctly terminated, and integrated with drainage before backfill.","required":true,"responseType":"check"},{"id":"res-found-013","prompt":"Masonry walls under construction are braced and limited-access zones are established where required.","required":true,"responseType":"check"},{"id":"res-found-014","prompt":"Foundation dimensions, elevations, diagonals, wall alignment, openings, and top-of-wall condition are accepted before framing begins.","required":true,"responseType":"check"}],"title":"Foundations, concrete, and masonry"},{"id":"framing-structure","items":[{"id":"res-frame-001","prompt":"Lumber, engineered wood, connectors, and fasteners match approved grades, sizes, treatments, exposure ratings, and product documents.","required":true,"responseType":"check"},{"id":"res-frame-002","prompt":"Sill plates, capillary breaks or gaskets, anchors, hold-downs, and corrosion protection are complete and correctly located.","required":true,"responseType":"check"},{"id":"res-frame-003","prompt":"Floor joists, beams, girders, posts, bearings, hangers, and connections match the approved structural documents.","required":true,"responseType":"check"},{"id":"res-frame-004","prompt":"Field holes, notches, cuts, and alterations in structural members are permitted by approved documents or written repair details.","required":true,"responseType":"check"},{"id":"res-frame-005","prompt":"Subfloor and sheathing panels have the required orientation, edge support, spacing, adhesive, and fastening without avoidable damage.","required":true,"responseType":"check"},{"id":"res-frame-006","prompt":"Walls are correctly located, plumb, aligned, connected, and temporarily braced until the permanent load path is complete.","required":true,"responseType":"check"},{"id":"res-frame-007","prompt":"Headers, lintels, posts, jack studs, bearing points, and concentrated-load paths match the approved design.","required":true,"responseType":"check"},{"id":"res-frame-008","prompt":"Shear walls, braced-wall panels, straps, hold-downs, blocking, and nailing match the approved lateral design.","required":true,"responseType":"check"},{"id":"res-frame-009","prompt":"Trusses are installed, restrained, braced, and connected according to the approved truss package and erection plan.","required":true,"responseType":"check"},{"id":"res-frame-010","prompt":"Trusses and engineered members have no unapproved cuts, drilled holes, damaged plates, or field modifications.","required":true,"responseType":"check"},{"id":"res-frame-011","prompt":"Roof rafters, ceiling joists, ridge elements, ties, uplift connectors, and point-load supports are complete and correctly connected.","required":true,"responseType":"check"},{"id":"res-frame-012","prompt":"Required fireblocking and draftstopping are complete at concealed vertical and horizontal pathways before cover.","required":true,"responseType":"check"},{"id":"res-frame-013","prompt":"Rough openings for stairs, windows, doors, attic access, chimneys, and equipment match approved dimensions and required clearances.","required":true,"responseType":"check"},{"id":"res-frame-014","prompt":"Material bundles and equipment are placed only where the incomplete structure can safely support them.","required":true,"responseType":"check"},{"id":"res-frame-015","prompt":"The framing inspection documents moisture damage, decay, splits, missing fasteners, and unresolved structural corrections before concealment.","required":true,"responseType":"check"}],"title":"Structural framing"},{"id":"falls-ladders-scaffolds","items":[{"id":"res-fall-001","prompt":"Workers engaged in residential construction at six feet or more above lower levels have compliant fall protection for the specific activity.","required":true,"responseType":"check"},{"id":"res-fall-002","prompt":"Floor holes, skylights, stair openings, and other openings are covered or guarded for both fall and falling-object exposure.","required":true,"responseType":"check"},{"id":"res-fall-003","prompt":"Personal fall-arrest or restraint equipment is inspected before use and removed from service when damaged or previously impact-loaded.","required":true,"responseType":"check"},{"id":"res-fall-004","prompt":"Fall-protection anchors, connectors, compatibility, clearance, swing-fall exposure, and rescue arrangements match the selected system.","required":true,"responseType":"check"},{"id":"res-fall-005","prompt":"Guardrail systems are complete, stable, correctly configured, and free of openings or conditions that defeat their protection.","required":true,"responseType":"check"},{"id":"res-fall-006","prompt":"Portable ladders are inspected and defective ladders are tagged or removed from service.","required":true,"responseType":"check"},{"id":"res-fall-007","prompt":"The ladder type, length, duty rating, material, and setup are suitable for the task and surrounding electrical conditions.","required":true,"responseType":"check"},{"id":"res-fall-008","prompt":"A portable ladder used for access extends at least three feet above the landing or has an equivalent secure grasping arrangement.","required":true,"responseType":"check"},{"id":"res-fall-009","prompt":"Non-self-supporting ladders are set at the required angle on stable footing and secured against displacement where needed.","required":true,"responseType":"check"},{"id":"res-fall-010","prompt":"Workers face the ladder, maintain a secure grasp, and do not carry loads that could cause loss of balance.","required":true,"responseType":"check"},{"id":"res-fall-011","prompt":"Scaffolds are erected, moved, altered, inspected, and dismantled under the required competent-person supervision.","required":true,"responseType":"check"},{"id":"res-fall-012","prompt":"Scaffold foundations, supports, ties, bracing, platforms, and load capacity are complete for the current configuration.","required":true,"responseType":"check"},{"id":"res-fall-013","prompt":"Scaffold users have safe access and do not climb cross-braces or use improvised access.","required":true,"responseType":"check"},{"id":"res-fall-014","prompt":"Required scaffold fall protection and falling-object protection are installed and maintained.","required":true,"responseType":"check"},{"id":"res-fall-015","prompt":"Ladders use nonconductive side rails where contact with exposed energized equipment is possible, and scaffolds maintain required clearance from energized power lines.","required":true,"responseType":"check"}],"title":"Falls, ladders, and scaffolds"},{"id":"roofing","items":[{"id":"res-roof-001","prompt":"The roofing pre-task plan addresses access, fall protection, openings, weather, material staging, debris, and rescue.","required":true,"responseType":"check"},{"id":"res-roof-002","prompt":"Roof-edge, steep-roof, low-slope-roof, and residential fall protection matches the roof and activity being performed.","required":true,"responseType":"check"},{"id":"res-roof-003","prompt":"Skylights, roof holes, access openings, and fragile surfaces are identified and protected before workers enter the roof area.","required":true,"responseType":"check"},{"id":"res-roof-004","prompt":"Material bundles and equipment are secured and distributed within the verified capacity of the roof structure.","required":true,"responseType":"check"},{"id":"res-roof-005","prompt":"Roof work is suspended or modified when wind, rain, frost, snow, lightning, heat, or visibility makes the planned controls ineffective.","required":true,"responseType":"check"},{"id":"res-roof-006","prompt":"Torch-applied roofing, hot work, adhesives, and heated equipment use the required permit, fire watch, extinguishers, and combustible controls.","required":true,"responseType":"check"},{"id":"res-roof-007","prompt":"The roof deck is accepted as sound, dry, clean, properly fastened, and within substrate tolerances before roofing is installed.","required":true,"responseType":"check"},{"id":"res-roof-008","prompt":"Roof slope, crickets, saddles, drainage paths, and penetrations match approved drawings without unintended ponding locations.","required":true,"responseType":"check"},{"id":"res-roof-009","prompt":"Underlayment, ice-barrier, starter, edge metal, and valley materials are the approved products and are installed in the required sequence.","required":true,"responseType":"check"},{"id":"res-roof-010","prompt":"Eave, rake, valley, wall, chimney, step, kick-out, and counterflashing details shed water onto the layer below.","required":true,"responseType":"check"},{"id":"res-roof-011","prompt":"Roof penetrations use compatible, approved flashing assemblies integrated with the drainage plane.","required":true,"responseType":"check"},{"id":"res-roof-012","prompt":"Roof-covering fastener type, location, spacing, embedment, and installation pressure match the approved system and wind requirements.","required":true,"responseType":"check"},{"id":"res-roof-013","prompt":"Shingle offsets or membrane laps, seams, terminations, and repairs meet the approved installation instructions without fishmouths or voids.","required":true,"responseType":"check"},{"id":"res-roof-014","prompt":"Roof-to-wall, roof-to-deck, dormer, sidewall, and lower-roof intersections include the approved drainage and flashing details.","required":true,"responseType":"check"},{"id":"res-roof-015","prompt":"Attic intake, exhaust, unvented-assembly details, and clearance from heat-producing equipment match the approved design.","required":true,"responseType":"check"},{"id":"res-roof-016","prompt":"Roofing accessories, sealants, adhesives, metals, and membranes are mutually compatible and within shelf-life and weather limitations.","required":true,"responseType":"check"},{"id":"res-roof-017","prompt":"Completed roofing is free of open seams, exposed unapproved fasteners, damaged surfacing, debris, blocked drainage, and unresolved punch items.","required":true,"responseType":"check"},{"id":"res-roof-018","prompt":"Required roofing inspection records, concealed-condition photos, product documentation, and warranty submissions are complete.","required":true,"responseType":"check"}],"title":"Roofing safety and quality"},{"id":"building-envelope","items":[{"id":"res-env-001","prompt":"The water-resistive barrier is continuous, correctly lapped, repaired at damage, and integrated with openings and adjacent assemblies.","required":true,"responseType":"check"},{"id":"res-env-002","prompt":"Exterior layers are sequenced in shingle fashion so each upper drainage component discharges onto the layer below.","required":true,"responseType":"check"},{"id":"res-env-003","prompt":"Window and door rough openings have the required size, support, surface condition, and drainage preparation before installation.","required":true,"responseType":"check"},{"id":"res-env-004","prompt":"Sill pans, end dams, jamb flashing, head flashing, and corner patches match the approved opening detail.","required":true,"responseType":"check"},{"id":"res-env-005","prompt":"Windows and exterior doors are the approved units and are installed plumb, level, square, anchored, sealed, and operable.","required":true,"responseType":"check"},{"id":"res-env-006","prompt":"Sealant joints have compatible materials, clean substrates, required backing, suitable geometry, and continuous adhesion.","required":true,"responseType":"check"},{"id":"res-env-007","prompt":"Cladding, trim, furring, and attachments maintain required clearances, fastening, movement joints, and drainage or ventilation spaces.","required":true,"responseType":"check"},{"id":"res-env-008","prompt":"Masonry veneer flashing, end dams, weeps, drainage space, ties, and base-of-wall discharge are complete before concealment.","required":true,"responseType":"check"},{"id":"res-env-009","prompt":"Exterior penetrations for utilities, fixtures, vents, and fasteners are supported, flashed, and sealed without blocking drainage.","required":true,"responseType":"check"},{"id":"res-env-010","prompt":"Deck ledgers, porch roofs, exterior stairs, landings, and intersecting roofs do not interrupt the wall drainage plane.","required":true,"responseType":"check"},{"id":"res-env-011","prompt":"Exterior materials and fasteners are compatible with treated wood, dissimilar metals, sealants, and expected exposure.","required":true,"responseType":"check"},{"id":"res-env-012","prompt":"Below-grade and above-grade air, water, vapor, and thermal control layers connect continuously at transitions.","required":true,"responseType":"check"},{"id":"res-env-013","prompt":"Required envelope mockups or field water tests use the approved procedure and all failures are corrected and retested.","required":true,"responseType":"check"},{"id":"res-env-014","prompt":"Concealed flashing, membrane transitions, penetrations, and repairs are photographed and accepted before cladding covers them.","required":true,"responseType":"check"}],"title":"Exterior walls, windows, doors, and flashing"},{"id":"plumbing","items":[{"id":"res-plumb-001","prompt":"Pipe, fittings, valves, fixtures, and equipment are approved for the service and match the accepted submittals.","required":true,"responseType":"check"},{"id":"res-plumb-002","prompt":"Water piping is supported, protected from damage, isolated from incompatible materials, and arranged for thermal movement.","required":true,"responseType":"check"},{"id":"res-plumb-003","prompt":"Drain, waste, and vent piping has the approved sizing, slope, support, fittings, cleanouts, and routing.","required":true,"responseType":"check"},{"id":"res-plumb-004","prompt":"Traps, trap arms, vents, primers, and prohibited cross-connections have been checked before concealment.","required":true,"responseType":"check"},{"id":"res-plumb-005","prompt":"Required water-supply, drainage, vent, and gas-system tests are completed with accepted results before concealment.","required":true,"responseType":"check"},{"id":"res-plumb-006","prompt":"Piping near framing faces is protected from fastener damage and does not contain unauthorized structural penetrations.","required":true,"responseType":"check"},{"id":"res-plumb-007","prompt":"Fixtures and supports are secure, aligned, accessible, and sealed at water-exposed transitions.","required":true,"responseType":"check"},{"id":"res-plumb-008","prompt":"Water-heater support, pan and drain, temperature-pressure relief discharge, clearances, and access match approved requirements.","required":true,"responseType":"check"},{"id":"res-plumb-009","prompt":"Fuel-fired water-heater combustion air, venting, draft, shutoff, and protection from vehicle impact are complete.","required":true,"responseType":"check"},{"id":"res-plumb-010","prompt":"Required backflow protection, pressure control, thermal-expansion control, and accessible shutoffs are installed.","required":true,"responseType":"check"},{"id":"res-plumb-011","prompt":"Water and drainage piping exposed to freezing or damaging heat is routed, insulated, or otherwise protected.","required":true,"responseType":"check"},{"id":"res-plumb-012","prompt":"Plumbing penetrations maintain required fireblocking, draftstopping, fire-resistance, and air or water control layers.","required":true,"responseType":"check"},{"id":"res-plumb-013","prompt":"The completed plumbing system is checked under operating conditions for leakage, drainage, fixture operation, temperature, and pressure.","required":true,"responseType":"check"}],"title":"Plumbing"},{"id":"hvac-fuel-gas","items":[{"id":"res-hvac-001","prompt":"HVAC, ventilation, and fuel-gas equipment match approved selections, capacities, efficiencies, and listed applications.","required":true,"responseType":"check"},{"id":"res-hvac-002","prompt":"Heating and cooling loads, equipment sizing, duct design, and ventilation design are available and coordinated with the installed system.","required":true,"responseType":"check"},{"id":"res-hvac-003","prompt":"Equipment and ducts are independently supported, protected from damage, and provided with required service access and clearances.","required":true,"responseType":"check"},{"id":"res-hvac-004","prompt":"Duct joints, seams, boots, plenums, air-handler connections, and building penetrations are sealed with approved materials.","required":true,"responseType":"check"},{"id":"res-hvac-005","prompt":"Duct and refrigerant-line insulation is continuous, correctly rated, protected, and sealed against condensation.","required":true,"responseType":"check"},{"id":"res-hvac-006","prompt":"Primary and auxiliary condensate management is sloped, trapped where required, terminated visibly or acceptably, and tested.","required":true,"responseType":"check"},{"id":"res-hvac-007","prompt":"Fuel-burning appliances have required combustion air, venting, clearances, draft provisions, and garage or vehicle-impact protection.","required":true,"responseType":"check"},{"id":"res-hvac-008","prompt":"Fuel-gas pipe material, sizing, support, protection, bonding, valves, and equipment connections match approved requirements.","required":true,"responseType":"check"},{"id":"res-hvac-009","prompt":"The fuel-gas system has passed the required pressure test before concealment or connection to service.","required":true,"responseType":"check"},{"id":"res-hvac-010","prompt":"Refrigerant piping is correctly joined, supported, protected, insulated, pressure-tested, evacuated, and documented.","required":true,"responseType":"check"},{"id":"res-hvac-011","prompt":"Bathroom, kitchen, and dryer exhaust systems discharge outdoors through approved, weather-protected terminations.","required":true,"responseType":"check"},{"id":"res-hvac-012","prompt":"Whole-house mechanical ventilation components, controls, intake locations, and airflow settings match the approved design.","required":true,"responseType":"check"},{"id":"res-hvac-013","prompt":"Mechanical and fuel-gas penetrations maintain required fireblocking, draftstopping, fire-resistance, and envelope layers.","required":true,"responseType":"check"},{"id":"res-hvac-014","prompt":"Startup, controls, airflow, balance, combustion safety, and functional test results are accepted and deficiencies are closed.","required":true,"responseType":"check"}],"title":"HVAC, ventilation, and fuel gas"},{"id":"electrical","items":[{"id":"res-elec-001","prompt":"Temporary 120-volt, 15- and 20-amp receptacle outlets used by employees have required GFCI protection or an implemented assured equipment grounding program.","required":true,"responseType":"check"},{"id":"res-elec-002","prompt":"Extension cords and portable electrical equipment are approved for the service, inspected, grounded when required, and free of improvised repairs.","required":true,"responseType":"check"},{"id":"res-elec-003","prompt":"Temporary panels, boxes, covers, knockouts, splices, and live parts are enclosed and protected from weather and physical damage.","required":true,"responseType":"check"},{"id":"res-elec-004","prompt":"Energized electrical work is avoided or controlled by authorized procedures, qualified workers, boundaries, and suitable protective equipment.","required":true,"responseType":"check"},{"id":"res-elec-005","prompt":"Service equipment, panels, disconnects, grounding electrodes, and bonding components match approved utility and project requirements.","required":true,"responseType":"check"},{"id":"res-elec-006","prompt":"Panel working space, access, identification, enclosure integrity, and protection from storage or damage are maintained.","required":true,"responseType":"check"},{"id":"res-elec-007","prompt":"Cable and raceway type, support, protection, bend, fill, and routing match approved requirements and environmental conditions.","required":true,"responseType":"check"},{"id":"res-elec-008","prompt":"Cables and raceways near framing faces are protected from fasteners and do not use unauthorized structural openings.","required":true,"responseType":"check"},{"id":"res-elec-009","prompt":"Boxes are approved, secure, accessible, correctly sized, and set for the finished surface without damaged entries or missing clamps.","required":true,"responseType":"check"},{"id":"res-elec-010","prompt":"Conductor size, insulation, identification, terminations, splices, and torque values match the circuit and equipment requirements.","required":true,"responseType":"check"},{"id":"res-elec-011","prompt":"Required permanent GFCI, AFCI, tamper-resistant, weather-resistant, and in-use protections are installed for the adopted code and location.","required":true,"responseType":"check"},{"id":"res-elec-012","prompt":"Receptacle, switch, lighting, appliance, disconnect, and dedicated-circuit locations match the approved plans and equipment instructions.","required":true,"responseType":"check"},{"id":"res-elec-013","prompt":"Smoke and carbon-monoxide alarm power, interconnection, locations, and listing match the adopted requirements and approved plans.","required":true,"responseType":"check"},{"id":"res-elec-014","prompt":"Equipment and luminaires in wet, damp, exterior, closet, attic, and insulated locations are listed and installed for the environment.","required":true,"responseType":"check"},{"id":"res-elec-015","prompt":"Electrical penetrations maintain required fireblocking, draftstopping, fire-resistance, and air or water control layers.","required":true,"responseType":"check"},{"id":"res-elec-016","prompt":"Required electrical inspections and functional tests are accepted, directories are accurate, and temporary wiring is removed when no longer needed.","required":true,"responseType":"check"}],"title":"Electrical and temporary power"},{"id":"insulation-air-moisture","items":[{"id":"res-insul-001","prompt":"The primary air barrier is identified and continuous at exterior assemblies, attached garages, ceilings, floors, and transitions.","required":true,"responseType":"check"},{"id":"res-insul-002","prompt":"Penetrations, top and bottom plates, rim areas, chases, dropped soffits, and service openings are sealed with durable compatible materials.","required":true,"responseType":"check"},{"id":"res-insul-003","prompt":"Insulation type, R-value, depth, density, and location match the approved energy design and product instructions.","required":true,"responseType":"check"},{"id":"res-insul-004","prompt":"Insulation is in full contact with the intended air barrier and has no avoidable gaps, voids, compression, wind washing, or misalignment.","required":true,"responseType":"check"},{"id":"res-insul-005","prompt":"Insulation and air-sealing materials maintain required clearance from flues, chimneys, heat-producing devices, and non-rated fixtures.","required":true,"responseType":"check"},{"id":"res-insul-006","prompt":"Attic ventilation baffles, insulation dams, access weatherstripping, and ventilation paths are complete for the approved assembly.","required":true,"responseType":"check"},{"id":"res-insul-007","prompt":"Vapor retarders and vapor-open or vapor-closed materials match the climate-specific approved wall, roof, floor, and crawlspace assemblies.","required":true,"responseType":"check"},{"id":"res-insul-008","prompt":"Walls behind tubs, showers, fireplaces, stairs, and other inaccessible areas have the required air barrier and insulation before closure.","required":true,"responseType":"check"},{"id":"res-insul-009","prompt":"Foam plastics, sealants, and penetration materials have the required listing, flame or thermal protection, and installation thickness.","required":true,"responseType":"check"},{"id":"res-insul-010","prompt":"Framing and concealed cavities are acceptably dry and free of unresolved bulk-water intrusion before insulation and interior cover.","required":true,"responseType":"check"},{"id":"res-insul-011","prompt":"Required blower-door and duct-leakage tests use the approved procedure and meet the project-specific target.","required":true,"responseType":"check"},{"id":"res-insul-012","prompt":"The insulation and air-sealing inspection is complete before concealed assemblies are covered.","required":true,"responseType":"check"}],"title":"Insulation, air sealing, and moisture control"},{"id":"fire-life-safety","items":[{"id":"res-life-001","prompt":"Required smoke alarms are listed, correctly located, powered, interconnected, unobstructed, and tested.","required":true,"responseType":"check"},{"id":"res-life-002","prompt":"Required carbon-monoxide alarms are listed, correctly located, powered, interconnected where required, and tested.","required":true,"responseType":"check"},{"id":"res-life-003","prompt":"Sleeping rooms and basements have the required emergency escape and rescue openings with operable, unobstructed clearances.","required":true,"responseType":"check"},{"id":"res-life-004","prompt":"Required egress doors, landings, locks, and travel paths are operable from the egress side without prohibited obstruction.","required":true,"responseType":"check"},{"id":"res-life-005","prompt":"Garage-to-dwelling separation, protected openings, duct limitations, and floor or ceiling protection are complete.","required":true,"responseType":"check"},{"id":"res-life-006","prompt":"Fireblocking and draftstopping close concealed pathways at required stories, soffits, chases, stairs, tubs, fireplaces, and penetrations.","required":true,"responseType":"check"},{"id":"res-life-007","prompt":"Penetrations and joints in fire-resistance-rated or smoke-resisting assemblies match a complete approved listed system.","required":true,"responseType":"check"},{"id":"res-life-008","prompt":"Required dwelling-unit separation walls, townhouse separation, continuity, and protected openings are complete and documented.","required":true,"responseType":"check"},{"id":"res-life-009","prompt":"Chimneys, fireplaces, vents, and heat-producing appliances maintain approved clearances and termination conditions.","required":true,"responseType":"check"},{"id":"res-life-010","prompt":"Foam plastic and other combustible insulation have the required thermal or ignition barrier and protected terminations.","required":true,"responseType":"check"},{"id":"res-life-011","prompt":"The street address is visible as required and emergency responders have usable access to the completed dwelling.","required":true,"responseType":"check"},{"id":"res-life-012","prompt":"Final life-safety testing verifies alarms, egress components, garage protection, and other required systems without unresolved critical defects.","required":true,"responseType":"check"}],"title":"Fire and life safety"},{"id":"interior-finishes","items":[{"id":"res-int-001","prompt":"Gypsum panel type, thickness, edge condition, orientation, support, and fastening match the approved assembly.","required":true,"responseType":"check"},{"id":"res-int-002","prompt":"Fire-resistance-rated gypsum assemblies use the complete listed layer sequence, joints, fasteners, backing, and penetrations.","required":true,"responseType":"check"},{"id":"res-int-003","prompt":"Required backing and blocking are installed for cabinets, guards, handrails, accessories, fixtures, and wall-mounted equipment.","required":true,"responseType":"check"},{"id":"res-int-004","prompt":"Wet-area substrates, membranes, seams, corners, penetrations, and transitions form the approved continuous water-control assembly.","required":true,"responseType":"check"},{"id":"res-int-005","prompt":"Shower receptors, curbs, drains, and waterproofing pass the required test before tile or finish installation.","required":true,"responseType":"check"},{"id":"res-int-006","prompt":"Floor substrates meet the finish manufacturer''s flatness, dryness, cleanliness, fastening, and movement-joint requirements.","required":true,"responseType":"check"},{"id":"res-int-007","prompt":"Cabinets, countertops, shelving, and heavy architectural components are securely anchored to suitable support.","required":true,"responseType":"check"},{"id":"res-int-008","prompt":"Interior doors, hardware, trim, and access panels operate correctly and maintain required clearances and access.","required":true,"responseType":"check"},{"id":"res-int-009","prompt":"Coatings, adhesives, solvents, and finish materials are stored, ventilated, mixed, and applied within their safety and environmental limits.","required":true,"responseType":"check"},{"id":"res-int-010","prompt":"Interior finishes are clean, complete, protected from damage, and free of unresolved functional or workmanship defects.","required":true,"responseType":"check"}],"title":"Interior finishes and wet areas"},{"id":"stairs-decks-guards","items":[{"id":"res-deck-001","prompt":"Deck ledgers have approved attachment, flashing, spacing, and connection to structurally suitable framing.","required":true,"responseType":"check"},{"id":"res-deck-002","prompt":"Deck footings, posts, beams, joists, bearings, hangers, and load paths match the approved structural design.","required":true,"responseType":"check"},{"id":"res-deck-003","prompt":"Required lateral-load, uplift, diagonal-bracing, and positive-connection details are complete.","required":true,"responseType":"check"},{"id":"res-deck-004","prompt":"Exterior connectors and fasteners are compatible with treated wood, other metals, and the exposure classification.","required":true,"responseType":"check"},{"id":"res-deck-005","prompt":"Stair risers, treads, winders, nosings, and landings are within approved dimensions and are uniform throughout each flight.","required":true,"responseType":"check"},{"id":"res-deck-006","prompt":"Required stair headroom, width, illumination, and clear travel path are maintained.","required":true,"responseType":"check"},{"id":"res-deck-007","prompt":"Required handrails are continuous where required, graspable, correctly located, securely anchored, and properly returned or terminated.","required":true,"responseType":"check"},{"id":"res-deck-008","prompt":"Required guards have approved height, opening limitations, attachment, continuity, and resistance to foreseeable loads.","required":true,"responseType":"check"},{"id":"res-deck-009","prompt":"Decking, porch flooring, and walking surfaces are securely fastened, slip-conscious, drained, and free of hazardous projections.","required":true,"responseType":"check"},{"id":"res-deck-010","prompt":"Exterior landings, thresholds, stairs, and ramps have approved geometry, support, drainage, and weather-resistant construction.","required":true,"responseType":"check"},{"id":"res-deck-011","prompt":"Completed stairs, decks, guards, and handrails have no movement, damage, missing connectors, or unresolved structural corrections.","required":true,"responseType":"check"}],"title":"Stairs, decks, guards, and handrails"},{"id":"exterior-drainage","items":[{"id":"res-ext-001","prompt":"Final grade, swales, drains, and hardscape direct surface water to approved locations without trapping it against the dwelling.","required":true,"responseType":"check"},{"id":"res-ext-002","prompt":"Gutters, downspouts, leaders, splash blocks, and underground connections are complete, secure, and discharge as designed.","required":true,"responseType":"check"},{"id":"res-ext-003","prompt":"Exterior slabs, walks, stoops, patios, and driveways have approved elevation, slope, joints, support, and separation from the structure.","required":true,"responseType":"check"},{"id":"res-ext-004","prompt":"Retaining walls, site walls, and freestanding exterior structures match approved footing, drainage, reinforcement, and height requirements.","required":true,"responseType":"check"},{"id":"res-ext-005","prompt":"Water, sewer, gas, electric, communications, and drainage services have approved separation, cover, protection, identification, and test records.","required":true,"responseType":"check"},{"id":"res-ext-006","prompt":"Irrigation, hose connections, condensate, sump discharge, and roof drainage do not direct water into foundations or vulnerable assemblies.","required":true,"responseType":"check"},{"id":"res-ext-007","prompt":"Landscape soil, mulch, vegetation, and irrigation maintain approved clearances from cladding, weeps, equipment, and wood framing.","required":true,"responseType":"check"},{"id":"res-ext-008","prompt":"Completed exterior routes are stable, drained, illuminated where required, and free of abrupt hazards or unprotected changes in elevation.","required":true,"responseType":"check"},{"id":"res-ext-009","prompt":"Construction fencing, temporary protections, dumpsters, and stored materials are removed or left in an approved safe turnover condition.","required":true,"responseType":"check"},{"id":"res-ext-010","prompt":"Where required, drainage testing or a documented rain observation confirms positive flow without leakage, erosion, or unintended ponding.","required":true,"responseType":"check"}],"title":"Exterior improvements and drainage"},{"id":"commissioning-closeout","items":[{"id":"res-close-001","prompt":"Required building, trade, special, utility, and third-party inspections have accepted results or documented approved resolution.","required":true,"responseType":"check"},{"id":"res-close-002","prompt":"Open punch-list, nonconformance, failed-test, and corrective-action items are assigned, tracked, and verified closed.","required":true,"responseType":"check"},{"id":"res-close-003","prompt":"Required structural, envelope, plumbing, gas, HVAC, electrical, energy, and life-safety test reports are complete and accepted.","required":true,"responseType":"check"},{"id":"res-close-004","prompt":"Mechanical equipment, plumbing fixtures, appliances, controls, exhaust systems, and safety devices operate through their intended modes.","required":true,"responseType":"check"},{"id":"res-close-005","prompt":"Final electrical, gas, water, drainage, and combustion-safety checks show no leakage, unsafe energization, or unresolved critical condition.","required":true,"responseType":"check"},{"id":"res-close-006","prompt":"Operation manuals, maintenance instructions, product data, test reports, and warranty documents are organized for turnover.","required":true,"responseType":"check"},{"id":"res-close-007","prompt":"Record drawings, approved changes, concealed-condition photos, equipment data, and finish selections reflect the completed work.","required":true,"responseType":"check"},{"id":"res-close-008","prompt":"Required certificates, approvals, permit closeout, and occupancy authorization are complete before occupancy or use.","required":true,"responseType":"check"},{"id":"res-close-009","prompt":"Labels, panel directories, shutoff identification, filter sizes, equipment access, keys, and remotes are complete and accurate.","required":true,"responseType":"check"},{"id":"res-close-010","prompt":"The owner orientation covers emergency shutoffs, alarms, ventilation, equipment operation, drainage maintenance, and warranty procedures.","required":true,"responseType":"check"},{"id":"res-close-011","prompt":"The dwelling and site are clean, secure, weather-tight, and free of construction debris, temporary hazards, and abandoned materials.","required":true,"responseType":"check"},{"id":"res-close-012","prompt":"No unresolved critical safety, structural, fire, electrical, fuel-gas, egress, or water-intrusion finding remains at turnover.","required":true,"responseType":"check"}],"title":"Testing, commissioning, and closeout"}],"version":1}',
   'published', 'system:audit-library', '2026-10-28T00:00:00.000Z');
